export function generateReport({
  evaluations,
  outputsPath,
  referencesPath,
  thresholds,
  generatedAt = new Date().toISOString()
}) {
  const totalSamples = evaluations.reduce((total, metric) => {
    if (typeof metric.total === 'number') return Math.max(total, metric.total);
    return total;
  }, 0);

  const report = {
    metadata: {
      generatedAt,
      outputsPath,
      referencesPath,
      totalSamples
    },
    metrics: evaluations
  };

  // Add threshold validation results if thresholds provided
  if (thresholds && typeof thresholds === 'object' && !Array.isArray(thresholds)) {
    const validation = validateThresholds(evaluations, thresholds);
    report.passed = validation.passed;
    report.thresholds = validation.thresholds;
  }

  return report;
}

