3	export function toJson(report) {
4	  return JSON.stringify(report, null, 2);
5	}
6	
7	export function toMarkdown(report) {
8	  const lines = [];
9	  lines.push('# FRAI Evaluation Report');
10	  lines.push('');
11	  lines.push(`- **Generated At:** ${report.metadata.generatedAt}`);
12	  lines.push(`- **Outputs File:** ${report.metadata.outputsPath}`);
13	  if (report.metadata.referencesPath) {
14	    lines.push(`- **References File:** ${report.metadata.referencesPath}`);
15	  }
16	  lines.push(`- **Total Samples:** ${report.metadata.totalSamples}`);
17	  lines.push('');
18	  lines.push('## Metrics');
19	  lines.push('');
20	  report.metrics.forEach((metric) => {
21	    lines.push(`### ${metric.label}`);
22	    lines.push('');
23	    lines.push(`- **Score:** ${metric.score ?? 'n/a'}`);
24	    if (typeof metric.total === 'number') {
25	      lines.push(`- **Total Samples:** ${metric.total}`);
26	    }
27	    if (typeof metric.matches === 'number') {
28	      lines.push(`- **Matches:** ${metric.matches}`);
29	    }
30	    if (typeof metric.flagged === 'number') {
31	      lines.push(`- **Flagged Samples:** ${metric.flagged}`);
32	    }
33	    if (typeof metric.averageDelta === 'number') {
34	      lines.push(`- **Average Delta:** ${metric.averageDelta}`);
35	    }
36	    lines.push('');
37	  });
38	  lines.push('---');
39	  lines.push('*Generated by FRAI Evaluation Harness*');
40	  return lines.join('\n');
41	}
42	
43	export function resolveReportPath(reportPath, format = 'json') {
44	  if (!reportPath) {
45	    return format === 'markdown' ? path.resolve('frai-eval-report.md') : path.resolve('frai-eval-report.json');
46	  }
47	  const ext = path.extname(reportPath);
48	  if (!ext) {
49	    return format === 'markdown' ? `${reportPath}.md` : `${reportPath}.json`;
50	  }
51	  return reportPath;
52	}
53	
