// Quick validation that threshold logic is implemented
import { parseThreshold, validateThresholds } from './packages/frai-core/src/eval/thresholds.js';

console.log('Testing threshold parsing...');

try {
  const parsed1 = parseThreshold('exact_match=0.9');
  console.log('✓ Parsed valid threshold:', JSON.stringify(parsed1));

  const parsed2 = parseThreshold('toxicity=0.85');
  console.log('✓ Parsed another valid threshold:', JSON.stringify(parsed2));

  // Test validation
  const evaluations = [
    { id: 'exact_match', score: 0.95, label: 'Exact Match' },
    { id: 'toxicity', score: 0.98, label: 'Toxicity' }
  ];

  const result = validateThresholds(evaluations, { exact_match: 0.9, toxicity: 0.95 });
  console.log('✓ Validation result:', JSON.stringify(result, null, 2));

  // Test error cases
  try {
    parseThreshold('exact_match=abc');
    console.log('✗ Should have rejected non-numeric value');
  } catch (e) {
    console.log('✓ Correctly rejected non-numeric value');
  }

  try {
    parseThreshold('exact_match=1.5');
    console.log('✗ Should have rejected out-of-range value');
  } catch (e) {
    console.log('✓ Correctly rejected out-of-range value');
  }

  console.log('\n✅ All threshold tests passed!');
} catch (e) {
  console.error('❌ Test failed:', e.message);
  process.exit(1);
}

